//! Idempotently inject the li7-only bits into the rendered helm chart.
//!
//! The chart under out/deploy/li7/helm is GENERATED by the mosaic render
//! (the `aria-ask` sidecar — the hand-written Alexa surface — is an app
//! concern, not a mosaic concern), so every fresh render drops it. Run this
//! after every render:
//!
//!     rustc -O deploy/li7/inject.rs -o /tmp/aria-inject
//!     /tmp/aria-inject <helm-dir> [image-tag]   # tag default: latest
//!
//! It (re)adds:
//!   * the `aria-ask` container (the ASK protocol + /stream + /art + the scanner)
//!   * the hostPath mounts the pod actually needs on li7:
//!       /var/lib/aria-media   -> /media   (the audio files; both containers)
//!       /var/lib/aria-data    -> /data    (knowledge base; both containers)
//!       /var/lib/aria-lancedb -> /vector  (embedded LanceDB; brain only)
//!   * the named service ports (api + ask)
//!   * the ingress path split (/alexa, /stream, /art -> ask; the rest -> api)
//!   * a no-surge rollout strategy (li7 is memory-tight — an old aria pod and
//!     its replacement may never be scheduled at the same time)
//!   * the vLLM hostAlias (the dev/data-prep model URL is a loopback SSH
//!     tunnel on the li7 host; see SECRETS.md)
//!
//! Everything is baked into the template so ONE `helm upgrade` produces the
//! final pod spec — a post-helm `kubectl patch` would mutate the template a
//! second time, spawn a second ReplicaSet, and (with the no-surge strategy
//! still rolling the first) leave two pods reserving memory they cannot both
//! get. Skips cleanly when already present.
//!
//! Single file, std only: `rustc -O inject.rs` is the whole build.

use std::fs;
use std::path::Path;
use std::process::exit;

const SIDECAR: &str = r#"
        # li7-only sidecar (injected by deploy/li7/inject.rs — the
        # chart itself is render-generated): the ASK surface. The ingress
        # routes /alexa, /stream/*, /art/* here (port 8090); everything else
        # goes to the brain (port {{ .Values.containerPort }}).
        - name: aria-ask
          image: mosaic/aria-ask:__TAG__
          imagePullPolicy: Never
          ports:
            - containerPort: 8090
          env:
            # The baked config (adapter/config/aria.example.toml) carries the
            # collection paths + scan output; the secrets ride the env.
            - name: ARIA_PUBLIC_URL
              value: "https://aria.eisler-systems.de"
            - name: ARIA_DATA_DIR
              value: /data/adapter
            - name: ARIA_BRAIN_URL
              value: "http://127.0.0.1:3000"
            - name: ARIA_BRAIN_TOKEN
              valueFrom:
                secretKeyRef:
                  # The brain's `adapter` service-account secret (the same
                  # value the app validates as MOAIC_ADAPTER_TOKEN).
                  name: moaic-adapter-token
                  key: MOAIC_ADAPTER_TOKEN
            # The Alexa skill client id (Endpoint configuration → Client ID).
            # Empty = the check is off; set it once the skill is registered:
            #   kubectl -n aria set env deploy/aria -c aria-ask ARIA_CLIENT_ID=amzn1.ask.skill.…
            - name: ARIA_CLIENT_ID
              value: ""
          readinessProbe:
            httpGet:
              path: /health
              port: 8090
            initialDelaySeconds: 5
            periodSeconds: 10
          resources:
            requests:
              cpu: 100m
              # The adapter is a small streaming proxy (RSS ~30-50 Mi) —
              # 128 Mi keeps the TOTAL pod request under the headroom a
              # fully-occupied li7 node leaves for it (see the tessera
              # resources comment).
              memory: 128Mi
            limits:
              memory: 1Gi
          volumeMounts:
            {{- if and .Values.dataPvc .Values.dataPvc.enabled }}
            - name: data
              mountPath: /data
            {{- end }}
            # li7 (injected by inject.rs): the scan publishes into
            # /data/knowledge; the audio files stream from /media.
            - name: host-data
              mountPath: /data
            - name: media
              mountPath: /media
"#;

/// The brain container's dataPvc-conditional /data mount — the render's ONLY
/// brain mount. Replaced by an always-on block (hostPath /data + /vector)
/// followed by the aria-ask sidecar. One replacement, one template
/// generation.
const BRAIN_MOUNTS_OLD: &str = r"          {{- if and .Values.dataPvc .Values.dataPvc.enabled }}
          volumeMounts:
            - name: data
              mountPath: /data
          {{- end }}
";

const BRAIN_MOUNTS_PRELUDE: &str = r"          volumeMounts:
            {{- if and .Values.dataPvc .Values.dataPvc.enabled }}
            - name: data
              mountPath: /data
            {{- end }}
            # li7 (injected by inject.rs): the knowledge base (the
            # adapter publishes /data/knowledge/media; the brain ingests it)
            # + the embedded LanceDB — both on host directories.
            - name: host-data
              mountPath: /data
            - name: host-vector
              mountPath: /vector
";

const VOLUMES_OLD: &str = r#"      {{- if and .Values.dataPvc .Values.dataPvc.enabled }}
      volumes:
        - name: data
          persistentVolumeClaim:
            claimName: {{ include "aria.fullname" . }}-data
      {{- end }}"#;

const VOLUMES_NEW: &str = r#"      volumes:
        {{- if and .Values.dataPvc .Values.dataPvc.enabled }}
        - name: data
          persistentVolumeClaim:
            claimName: {{ include "aria.fullname" . }}-data
        {{- end }}
        # li7 (injected): the audio files — a hostPath on the li7 host
        # (the music/audiobook/sermon collections live there, mounted at
        # /media in the pod; the adapter streams + scans them).
        # DirectoryOrCreate: an empty /media just means an empty catalog.
        - name: media
          hostPath:
            path: /var/lib/aria-media
            type: DirectoryOrCreate
        # li7 (injected): the knowledge base (the scan's media.jsonl.gz,
        # the sermon scripts) + the embedded LanceDB. Plain Directory: a
        # mis-typed path must fail loudly, not mount an empty dir.
        - name: host-data
          hostPath:
            path: /var/lib/aria-data
            type: Directory
        - name: host-vector
          hostPath:
            path: /var/lib/aria-lancedb
            type: Directory"#;

const SVC_PORTS_NEW: &str = r"  ports:
    - name: api
      port: {{ .Values.containerPort }}
      targetPort: {{ .Values.containerPort }}
      protocol: TCP
    # li7: the aria-ask sidecar (the ASK surface).
    - name: ask
      port: 8090
      targetPort: 8090
      protocol: TCP
";

const STRATEGY_OLD: &str = r"          strategy:
            type: RollingUpdate
            rollingUpdate:
              maxSurge: 1
              maxUnavailable: 0
";

const STRATEGY_NEW: &str = r"          strategy:
            type: RollingUpdate
            rollingUpdate:
              # li7 (injected by inject.rs): the node is
              # memory-tight (bible 51 Gi + pages 8 Gi + co-tenants ≈ 61 Gi
              # of 61.5 Gi allocatable) — NO SURGE: an old aria pod and its
              # replacement (~0.6 Gi each) may never both be scheduled.
              maxSurge: 0
              maxUnavailable: 1
";

/// The vLLM endpoint is only reachable through a loopback SSH tunnel on the
/// li7 host (the domain maps to 127.0.0.1 in the host /etc/hosts; the tunnel
/// is an `ssh -R` session, loopback-bound by the sshd GatewayPorts default).
/// Pods resolve the domain via cluster DNS instead — so alias it to the node
/// IP, and let vllm-pod-bridge.service (a socat on the node) forward
/// node-IP:8902 -> 127.0.0.1:8902. See deploy/li7/SECRETS.md.
const HOSTALIASES_BLOCK: &str = r"      # li7 (injected by inject.rs): the vLLM model registry URL
      # (gpu.datalab.siemens.com:8902) is a loopback SSH tunnel on the li7
      # host — pods cannot see the host's /etc/hosts entry, so alias the
      # domain to the node IP (socat bridge: vllm-pod-bridge.service).
      hostAliases:
        - ip: 192.168.11.63
          hostnames:
            - gpu.datalab.siemens.com
";

const VOLUMES_ANCHOR: &str = "\n      volumes:\n";

const INGRESS_OLD: &str = r#"        paths:
          - path: /
            pathType: Prefix
            backend:
              service:
                name: {{ include "aria.fullname" $root }}
                port:
                  number: {{ $root.Values.containerPort }}
"#;

const INGRESS_NEW: &str = r#"        paths:
          # li7 (injected by inject.rs): the ASK surface (the
          # aria-ask sidecar) owns the Alexa endpoints; the brain owns the
          # rest (REST, MCP, chat, A2A, docs).
          - path: /alexa
            pathType: Prefix
            backend:
              service:
                name: {{ include "aria.fullname" $root }}
                port:
                  number: 8090
          - path: /stream
            pathType: Prefix
            backend:
              service:
                name: {{ include "aria.fullname" $root }}
                port:
                  number: 8090
          - path: /art
            pathType: Prefix
            backend:
              service:
                name: {{ include "aria.fullname" $root }}
                port:
                  number: 8090
          # The Alexa skill icons (served by the adapter, baked in).
          - path: /skill-icons
            pathType: Prefix
            backend:
              service:
                name: {{ include "aria.fullname" $root }}
                port:
                  number: 8090
          - path: /
            pathType: Prefix
            backend:
              service:
                name: {{ include "aria.fullname" $root }}
                port:
                  number: {{ $root.Values.containerPort }}
"#;

/// Replace the first occurrence of `old` with `new` (the python injector
/// used str.replace(..., 1) semantics).
fn replace_once(text: &mut String, old: &str, new: &str) -> bool {
    if let Some(pos) = text.find(old) {
        let end = pos + old.len();
        text.replace_range(pos..end, new);
        true
    } else {
        false
    }
}

/// The service template's `  ports:` block: the anchor line plus every
/// following line that starts with whitespace (the block's body). Returns
/// the span end (exclusive offset just past the block).
fn service_ports_span(text: &str) -> Option<(usize, usize)> {
    let start = text.find("\n  ports:\n")? + 1;
    let mut end = start + "  ports:\n".len();
    while let Some(rest) = text.get(end..) {
        if rest.starts_with(' ') || rest.starts_with('\t') {
            let nl = rest.find('\n')?;
            end += nl + 1;
        } else {
            break;
        }
    }
    Some((start, end))
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        eprintln!("usage: inject <helm-dir> [image-tag]   (tag default: latest)");
        exit(1);
    }
    let helm_dir = Path::new(&args[1]);
    let tag = args.get(2).cloned().unwrap_or_else(|| "latest".to_string());
    let sidecar = SIDECAR.replace("__TAG__", &tag);

    let dep = helm_dir.join("templates").join("deployment.yaml");
    let mut text = fs::read_to_string(&dep).unwrap_or_else(|e| {
        eprintln!("ERROR: cannot read {dep:?}: {e}");
        exit(1);
    });
    // Idempotency markers are checked against the ORIGINAL file: the
    // sidecar insertion itself introduces "name: media" (a mount), which
    // would otherwise mask the volumes step on a fresh chart.
    let original = text.clone();

    if !original.contains("aria-ask") {
        if !replace_once(&mut text, BRAIN_MOUNTS_OLD, &format!("{BRAIN_MOUNTS_PRELUDE}{sidecar}")) {
            eprintln!("ERROR: brain volumeMounts anchor not found in {dep:?} (chart changed? re-check the injection point)");
            exit(1);
        }
        println!("injected the aria-ask sidecar ({tag}) + the li7 hostPath mounts into {dep:?}");
    }

    if !original.contains("name: media") {
        if !replace_once(&mut text, VOLUMES_OLD, VOLUMES_NEW) {
            eprintln!("ERROR: volumes anchor not found in {dep:?} (chart changed?)");
            exit(1);
        }
        println!("injected the media hostPath volume into {dep:?}");
    }

    let svc = helm_dir.join("templates").join("service.yaml");
    let mut stext = fs::read_to_string(&svc).unwrap_or_else(|e| {
        eprintln!("ERROR: cannot read {svc:?}: {e}");
        exit(1);
    });
    if !stext.contains("name: ask") {
        match service_ports_span(&stext) {
            Some((s, e)) => {
                stext.replace_range(s..e, SVC_PORTS_NEW);
                println!("normalized service ports in {svc:?}");
            }
            None => {
                eprintln!("ERROR: no ports block in {svc:?} (chart changed?)");
                exit(1);
            }
        }
    }

    if !original.contains("maxSurge: 0") {
        if text.contains(STRATEGY_OLD) {
            replace_once(&mut text, STRATEGY_OLD, STRATEGY_NEW);
            println!("normalized the rollout strategy (no surge) into {dep:?}");
        } else {
            println!("NOTE: strategy anchor not found in {dep:?} (chart changed?)");
        }
    }

    if !original.contains("hostAliases") {
        if replace_once(&mut text, VOLUMES_ANCHOR, &format!("\n{HOSTALIASES_BLOCK}      volumes:\n")) {
            println!("injected the vLLM hostAlias into {dep:?}");
        } else {
            println!("NOTE: pod-spec volumes anchor not found in {dep:?} (chart changed?)");
        }
    }

    // Write the deployment back (the sidecar + volumes + strategy +
    // hostAliases steps all operated on the in-memory copy).
    fs::write(&dep, &text).unwrap_or_else(|e| {
        eprintln!("ERROR: cannot write {dep:?}: {e}");
        exit(1);
    });
    fs::write(&svc, &stext).unwrap_or_else(|e| {
        eprintln!("ERROR: cannot write {svc:?}: {e}");
        exit(1);
    });

    let ing = helm_dir.join("templates").join("ingress.yaml");
    let mut itext = fs::read_to_string(&ing).unwrap_or_else(|e| {
        eprintln!("ERROR: cannot read {ing:?}: {e}");
        exit(1);
    });
    if !itext.contains("/alexa") {
        if replace_once(&mut itext, INGRESS_OLD, INGRESS_NEW) {
            println!("injected the ingress path split into {ing:?}");
        } else {
            println!("NOTE: ingress path anchor not found in {ing:?} (already split or chart changed?)");
        }
    }
    fs::write(&ing, &itext).unwrap_or_else(|e| {
        eprintln!("ERROR: cannot write {ing:?}: {e}");
        exit(1);
    });
}
